function nitroCampaignQueue(){
  const status=state.session?.nitroCampaignState||{},platforms=['instagram',...['facebook','linkedin','tiktok'].filter(platform=>publicAutoPublishReady(platform,socialConnection(platform)))];
  return NITRO_CAMPAIGN_QUEUE.flatMap(post=>platforms.map(platform=>{
    const legacy=status[post.id]||{},saved=legacy.platforms?.[platform]||(platform==='instagram'?legacy:{});
    return {...post,id:`${post.id}:${platform}`,groupId:post.id,platform,...saved,status:saved.status||(saved.mediaId?'published':'scheduled')};
  }));
}
