function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function normalizedHex(value,fallback){return /^#[0-9a-f]{6}$/i.test(String(value||''))?String(value):fallback;}
function mixHex(a,b,amount){const left=normalizedHex(a,'#000000').slice(1),right=normalizedHex(b,'#000000').slice(1),mix=n=>Math.round(parseInt(left.slice(n,n+2),16)*(1-amount)+parseInt(right.slice(n,n+2),16)*amount).toString(16).padStart(2,'0');return '#'+mix(0)+mix(2)+mix(4);}
function workspaceTheme(primaryValue,secondaryValue){const primary=normalizedHex(primaryValue,'#ff6b00'),secondary=normalizedHex(secondaryValue,'#ffb000'),primarySoft=mixHex(primary,'#ffffff',.18),bg=mixHex('#050505',primary,.1),bg2=mixHex('#090909',secondary,.08),panel=mixHex('#111111',primary,.13),panel2=mixHex('#0b0b0b',secondary,.1),sidebar=mixHex('#070707',primary,.12);return `#customer-shell,.modal-overlay{--green:${primary};--green2:${primarySoft};--aqua:${secondary};--purple:${secondary};--line2:${primary}52;--workspace-primary:${primary};--workspace-secondary:${secondary}}#customer-shell{--workspace-bg:${bg};--workspace-bg2:${bg2};--workspace-panel:${panel};--workspace-panel2:${panel2};background:${bg}}#customer-shell .main-area{background:radial-gradient(circle at 82% -8%,${primary}26,transparent 34%),radial-gradient(circle at 5% 92%,${secondary}17,transparent 31%),linear-gradient(155deg,${bg},${bg2})}#customer-shell .sidebar{background:linear-gradient(180deg,${sidebar}f5,${bg}f2)!important;border-color:${primary}2e!important}#customer-shell .app-topbar{background:${bg}d9!important;border-color:${primary}26!important}#customer-shell .glass-card,#customer-shell .stat-card,#customer-shell .module-card,#customer-shell .settings-panel,#customer-shell .settings-nav{background:linear-gradient(145deg,${panel}f2,${panel2}e8)!important;border-color:${primary}24!important}#customer-shell .workspace-switch,#customer-shell .quick-action,#customer-shell .notice,#customer-shell .input,#customer-shell .select,#customer-shell .textarea,#customer-shell .icon-btn{background:${panel2}!important;border-color:${primary}2e!important}#customer-shell .side-link:hover,#customer-shell .settings-link:hover{background:${primary}14!important}.modal-overlay .modal-card{background:linear-gradient(155deg,${panel},${panel2})!important;border-color:${primary}55!important}`;}
function applyWorkspaceTheme(){let style=document.getElementById('workspace-brand-theme');const shell=document.getElementById('customer-shell');if(!shell){style?.remove();return;}if(!style){style=document.createElement('style');style.id='workspace-brand-theme';document.head.appendChild(style);}const data=state.session?.user?.onboarding?.data||{};style.textContent=workspaceTheme(data.primaryColor,data.secondaryColor);}
function money(value){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(value||0);}
function moneyExact(value){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(value||0);}
function initials(user){return ((user?.firstName?.[0]||'A')+(user?.lastName?.[0]||'')).toUpperCase();}
function plan(id){return PLANS[id]||PLANS.free;}
function qs(name){return new URLSearchParams(location.search).get(name)||'';}
function route(){return location.pathname.replace(/\/+$/,'')||'/';}
function toast(message,type=''){const el=document.createElement('div');el.className='toast '+type;el.textContent=message;toastRegion.appendChild(el);setTimeout(()=>el.remove(),3600);}
function setBusy(button,busy,label){if(!button)return;if(!button.dataset.label)button.dataset.label=button.textContent;button.disabled=busy;button.textContent=busy?(label||'Working…'):button.dataset.label;}

async function api(url,options={}){
  const response=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});
  const data=await response.json().catch(()=>({}));
  if(!response.ok){const error=new Error(data.error||'Request failed');error.code=data.code;error.data=data;throw error;}
  return data;
}

