function reportHtml(a){const r=a.report||{},scores=r.scores||{};return `<span class="eyebrow">NITRO GROWTH AUDIT</span><div class="audit-report-head"><div><h1>${esc(r.siteName||a.businessName||'Website audit')}</h1><p>${esc(a.website||'')}</p></div><div class="audit-score"><b>${Number(r.overallScore||0)}</b><small>/100</small></div></div><p class="audit-summary">${esc(r.summary||'')}</p><div class="audit-score-grid">${Object.entries(scores).map(([k,v])=>`<div><span>${esc(k.replace(/([A-Z])/g,' $1'))}</span><b>${Number(v||0)}</b></div>`).join('')}</div><div class="audit-columns"><section><h3>What is working</h3><ul>${(r.strengths||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Quick wins</h3><ol>${(r.quickWins||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section><section><h3>Highest-impact findings</h3>${(r.issues||[]).map(x=>`<article class="audit-issue"><span>${esc(x.severity||'medium')}</span><h4>${esc(x.title||'Finding')}</h4><p>${esc(x.evidence||'')}</p><b>Fix: ${esc(x.fix||'')}</b><small>${esc(x.impact||'')}</small></article>`).join('')}</section></div><div class="notice green"><b>Recommended next step:</b> ${esc(r.recommendedNextStep||'Prioritize the highest-impact conversion improvements.')}</div><p class="audit-limit">${(r.limitations||[]).map(esc).join(' · ')}</p><a class="btn btn-primary btn-lg" href="/signup">Build your growth system with Nitro →</a>`;}

