function selectedCheckout(){const id=qs('plan')||sessionStorage.getItem('nitro-plan')||'growth';const interval=qs('interval')||sessionStorage.getItem('nitro-interval')||state.interval;const chosen=plan(id);sessionStorage.setItem('nitro-plan',chosen.id);sessionStorage.setItem('nitro-interval',interval);return {chosen,interval,amount:interval==='yearly'?chosen.yearly:chosen.monthly};}
function checkoutSteps(active){return `<div class="checkout-steps">${['Review','Payment','Complete'].map((x,i)=>`${i?'<span class="checkout-line"></span>':''}<span class="checkout-step ${i<active?'done':i===active?'active':''}"><i>${i<active?'✓':i+1}</i>${x}</span>`).join('')}</div>`;}
function orderSummary(data,button=''){return `<aside class="checkout-card order-summary"><span class="plan-pill">${data.chosen.name} plan</span><div class="summary-price">${money(data.amount)}<small>/${data.interval==='yearly'?'year':'month'}</small></div><p>${data.chosen.desc}</p><ul class="feature-list">${data.chosen.features.slice(0,6).map(x=>`<li>${x}</li>`).join('')}</ul><div class="summary-total"><span>Due today · 14-day trial</span><strong>$0</strong></div><div class="summary-total"><span>After trial</span><strong>${money(data.amount)}</strong></div>${button}</aside>`;}
function renderCheckout(){document.title='Review your plan — Nitro Outreach';const data=selectedCheckout();return `<div class="checkout-wrap">${publicNav()}<main class="checkout-main">${checkoutSteps(0)}<div class="checkout-grid"><section class="checkout-card"><span class="eyebrow">Plan review</span><h1>Confirm your selection</h1><p>Review your plan and billing cadence before continuing to secure payment.</p><div class="review-list"><div class="review-row"><span>Plan</span><strong>${data.chosen.name}</strong></div><div class="review-row"><span>Billing</span><strong>${data.interval==='yearly'?'Annual':'Monthly'}</strong></div><div class="review-row"><span>Renewal</span><strong>Automatic until canceled</strong></div><div class="review-row"><span>Trial</span><strong>14 days</strong></div></div><div style="display:flex;gap:9px;margin-top:25px"><a class="btn" href="/pricing">Change plan</a><a class="btn btn-primary" href="/checkout/payment?plan=${data.chosen.id}&interval=${data.interval}">Continue to payment →</a></div></section>${orderSummary(data)}</div></main></div>`;}
function renderPayment(){document.title='Payment — Nitro Outreach';const data=selectedCheckout();const demo=!state.session?.stripeConfigured;return `<div class="checkout-wrap">${publicNav()}<main class="checkout-main">${checkoutSteps(1)}<div class="checkout-grid"><section class="checkout-card"><span class="eyebrow">Secure checkout</span><h1>${demo?'Preview payment flow':'Continue to Stripe'}</h1><p>${demo?'Stripe is not connected yet. This screen demonstrates the complete handoff and starts a no-charge demo trial.':'Your card details are entered on Stripe’s secure checkout. Nitro never stores your full card number.'}</p>${demo?'<div class="demo-banner"><b>DEMO CHECKOUT</b><br>No card will be charged. A trialing subscription record will be created so you can test the customer experience.</div>':'<div class="stripe-handoff"><div class="stripe-lock">▣</div><div><b>Secure payment powered by Stripe</b><p>Start with 14 days free. Stripe collects your payment method and handles future renewals securely.</p></div></div>'}<button id="activate-plan" class="btn btn-primary btn-block btn-lg">${demo?'Start demo trial':'Continue to secure checkout →'}</button><div class="form-status" id="form-status"></div></section>${orderSummary(data)}</div></main></div>`;}
function renderSuccess(){document.title='Subscription active — Nitro Outreach';const p=plan(state.session?.user?.subscription?.plan);return `<div class="checkout-wrap">${publicNav()}<main class="checkout-main">${checkoutSteps(2)}<section class="checkout-card success-card"><div class="success-icon">✓</div><span class="eyebrow">Setup complete</span><h1>Your ${p.name} workspace is ready.</h1><p>${state.session?.user?.subscription?.billingMode==='demo'?'Your no-charge demo subscription is active. Connect Stripe before accepting real customer payments.':'Your subscription is active and your workspace limits have been updated.'}</p><a class="btn btn-primary btn-lg" href="${state.session?.user?.onboarding?.completed?'/app':'/welcome'}">Continue to workspace →</a></section></main></div>`;}

