    const averages=data.averages||{};
    if(summary)summary.innerHTML=[['Posts synced',totals.posts,'Latest published media'],['Views',totals.views,`${socialMetric(averages.views)} average per post`],['Engagement rate',Number.isFinite(averages.engagementRate)?averages.engagementRate.toFixed(1)+'%':'—','Interactions divided by reach'],['Tracked clicks',totals.clicks,'Unique Nitro link clicks'],['Attributed leads',totals.leads,'Email captures from post links'],['Attributed signups',totals.signups,'Accounts created from post links']].map(item=>`<article class="glass-card"><small>${item[0]}</small><strong>${typeof item[1]==='string'?esc(item[1]):socialMetric(item[1])}</strong><span>${item[2]}</span></article>`).join('');
