function socialCalendar(drafts){
  const today=new Date();today.setHours(0,0,0,0);
  const end=new Date(today);end.setDate(today.getDate()+7);
  const scheduled=drafts.filter(item=>item.scheduledFor&&item.status!=='draft'&&Date.parse(item.scheduledFor)>=today.getTime()&&Date.parse(item.scheduledFor)<end.getTime()).sort((a,b)=>Date.parse(a.scheduledFor)-Date.parse(b.scheduledFor));
  const days=Array.from({length:7},(_,index)=>{const date=new Date(today);date.setDate(today.getDate()+index);return {key:date.toLocaleDateString(undefined,{year:'numeric',month:'2-digit',day:'2-digit'}),date,items:[]};});
  scheduled.forEach(item=>{const date=new Date(item.scheduledFor),key=date.toLocaleDateString(undefined,{year:'numeric',month:'2-digit',day:'2-digit'});const day=days.find(entry=>entry.key===key);if(day)day.items.push(item);});
  const groupedDays=days.map(day=>({...day,groups:Array.from(day.items.reduce((map,item)=>{const key=item.groupId||item.id;const group=map.get(key)||{...item,platforms:[]};group.platforms.push(item);map.set(key,group);return map;},new Map()).values())}));
  const legend=SOCIAL_CHANNELS.map(channel=>`<span><i style="--platform-color:${channel.color}"></i>${channel.name}</span>`).join('');
  const postCount=groupedDays.reduce((total,day)=>total+day.groups.length,0);
  return `<section class="glass-card social-calendar"><div class="panel-head"><div><span class="eyebrow">NEXT 7 DAYS</span><h3>Publishing calendar</h3><p>Every day stays visible, including weekends. One card represents one creative across all selected channels.</p></div><span>${postCount} UPCOMING POST${postCount===1?'':'S'}</span></div><div class="social-calendar-legend"><div>${legend}</div><div><span class="content-key is-image">Image</span><span class="content-key is-video">Video</span><span class="content-key is-text">Text</span><span class="content-key is-carousel">Carousel</span></div></div><div class="social-calendar-days">${groupedDays.map((day,index)=>`<article class="${day.groups.length?'':'is-empty-day'}"><header><small>${index===0?'TODAY':day.date.toLocaleDateString(undefined,{weekday:'short'}).toUpperCase()}</small><b>${day.date.toLocaleDateString(undefined,{month:'short',day:'numeric'})}</b></header><div>${day.groups.length?day.groups.map(item=>{const content=socialContentMeta(item);return `<span class="calendar-post type-${content.type}" data-full-caption="${esc(item.text||'')}" data-campaign-id="${item.systemCampaign?esc(item.groupId||''):''}" style="--content-color:${content.color}"><em>${new Date(item.scheduledFor).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}</em><strong>${content.label}</strong><small>${esc(String(item.text||'').slice(0,54))}</small><span class="calendar-platforms">${item.platforms.map(job=>{const platform=socialPlatformMeta(job.platform||'instagram');return `<b class="calendar-platform s-${esc(job.status||'scheduled')}" style="--platform-color:${platform.color}" title="${esc(platform.name)} · ${esc(job.status||'scheduled')}">${platform.mark}</b>`;}).join('')}</span></span>`;}).join(''):'<div class="social-empty-simple"><b>No post scheduled</b><span>Use + Create post to fill this day</span></div>'}</div></article>`).join('')}</div></section>`;
}
