    const s=d.stats||{},log=d.log||[];
    const beta=document.getElementById('beta-candidates');if(beta){const followups=new Map();log.filter(entry=>entry.followUpOf).forEach(entry=>{const list=followups.get(entry.followUpOf)||[];list.push(entry);followups.set(entry.followUpOf,list);});const candidates=log.filter(entry=>!entry.followUpOf&&entry.confirmedVisit&&!entry.replied&&!entry.unsubscribed).slice(0,8);beta.innerHTML=candidates.length?candidates.map((entry,index)=>{const sent=followups.get(entry.id)||[],followedUp=sent.some(item=>Number(item.sequence||0)>=2),visitAt=Number(entry.firstConfirmedAt||0),dueAt=visitAt+24*60*60*1000,status=entry.signup?'Signed up':followedUp?'Follow-up sent':Date.now()>=dueAt?'Sending on next hourly run':'Waiting 24 hours';const draft=`Hi ${entry.contactName||'there'} team — Nitro puts website building, social content and scheduling, tracked outreach, and visitor analytics in one workspace. For ${entry.contactName||'your business'}, that can keep the work and the results together instead of spread across separate tools. The free plan does not require a card: nitrooutreach.com`;return `<article class="${entry.signup?'is-converted':''}"><span>${esc(status)}</span><h4>${esc(entry.contactName||'Independent business')}</h4><p>${esc(entry.businessLocation||entry.targetSegment||'Qualified outreach lead')}</p><small>Confirmed visit · ${mountainTime(visitAt)} · due ${mountainTime(dueAt)}</small><button class="btn btn-sm" type="button" data-beta-copy="${index}">Copy personalized note</button><textarea hidden data-beta-draft="${index}">${esc(draft)}</textarea></article>`;}).join(''):'<div class="empty-state"><h3>No confirmed visitor waiting</h3><p>A business appears here only after Nitro confirms a real site visit.</p></div>';beta.querySelectorAll('[data-beta-copy]').forEach(button=>button.addEventListener('click',async()=>{const draft=beta.querySelector(`[data-beta-draft="${button.dataset.betaCopy}"]`)?.value||'';try{await navigator.clipboard.writeText(draft);toast('Personalized note copied','success');}catch{toast('Could not copy note','error');}}));}
    const startLabel=d.trackingStart?mountainTime(d.trackingStart):'the clean tracking cutoff',siteVisitStart=Date.parse(d.siteVisitTrackingStart||0);
    const note=document.getElementById('outreach-tracking-note');if(note){const webhookStatus=d.webhook?.status==='active'?'connected':d.webhook?.status==='restricted_api_key'?'needs a full-access Resend key':'needs attention';note.textContent='Clean stats started '+startLabel+' · provider tracking '+webhookStatus+(d.webhook?.reason?' ('+d.webhook.reason+')':'')+' · Link loads may be scanners. Confirmed visits require active on-site engagement. Opens remain estimates.';}
    const sg=document.getElementById('outreach-stats');
