function animateUI(){if(!state.hasRendered){const clearEntryTransform=()=>root.classList.remove('render-enter');root.classList.add('render-enter');root.addEventListener('animationend',clearEntryTransform,{once:true});setTimeout(clearEntryTransform,500);state.hasRendered=true;}root.querySelectorAll('.stat-value').forEach(el=>{const raw=el.textContent.trim(),match=raw.match(/^(\$?)([\d,]+)(%?)$/);if(!match)return;const target=Number(match[2].replace(/,/g,''));if(!Number.isFinite(target)||target===0)return;const prefix=match[1],suffix=match[3],start=performance.now(),duration=Math.min(900,420+target*.8);el.dataset.counting='1';const tick=now=>{const p=Math.min(1,(now-start)/duration),eased=1-Math.pow(1-p,3),value=Math.round(target*eased);el.textContent=prefix+value.toLocaleString()+suffix;if(p<1)requestAnimationFrame(tick);else delete el.dataset.counting;};requestAnimationFrame(tick);});}
function analyticsId(storage,key){try{let id=storage.getItem(key);if(!id){id=(crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2));storage.setItem(key,id);}return id;}catch{return Date.now()+'-'+Math.random().toString(36).slice(2);}}
function trackFunnelStage(stage){const key='nitro-funnel-'+stage;if(sessionStorage.getItem(key))return;sessionStorage.setItem(key,'1');const params=new URLSearchParams(location.search);fetch('/api/track-funnel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({stage,visitorId:analyticsId(localStorage,'nitro-visitor-id'),path:location.pathname,source:params.get('source')||params.get('utm_source')||'',webdriver:navigator.webdriver===true,visibility:document.visibilityState})}).catch(()=>sessionStorage.removeItem(key));}
function outreachAttribution(){try{return JSON.parse(sessionStorage.getItem('nitro-outreach-attribution')||'{}');}catch{return {};}}
function confirmOutreachVisit(reason){if(window.__nitroOutreachConfirmed)return;const attribution=outreachAttribution();if(!attribution.id||!attribution.token)return;window.__nitroOutreachConfirmed=true;fetch('/api/track-visit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({visitorId:analyticsId(localStorage,'nitro-visitor-id'),sessionId:analyticsId(sessionStorage,'nitro-visit-session-v2'),path:location.pathname+location.hash,outreachId:attribution.id,outreachToken:attribution.token,outreachEngagement:reason,webdriver:navigator.webdriver===true,visibility:document.visibilityState})}).catch(()=>{window.__nitroOutreachConfirmed=false;});}
function bindOutreachEngagement(){const attribution=outreachAttribution();if(!attribution.id||!attribution.token||window.__nitroOutreachEngagementBound)return;window.__nitroOutreachEngagementBound=true;let activeMs=0,lastTick=Date.now();setInterval(()=>{const now=Date.now();if(document.visibilityState==='visible'&&document.hasFocus())activeMs+=now-lastTick;lastTick=now;if(activeMs>=8000)confirmOutreachVisit('active_8s');},1000);addEventListener('scroll',()=>{const available=Math.max(0,document.documentElement.scrollHeight-innerHeight);if(scrollY>=Math.min(160,available*.2))confirmOutreachVisit('scroll');},{passive:true});document.addEventListener('click',event=>{if(event.isTrusted&&event.target.closest('a,button,input[type="submit"],[role="button"]'))confirmOutreachVisit('click');});}
function trackPageView(){try{if((state.session?.user?.email||'').toLowerCase()===OWNER_EMAIL){localStorage.setItem('nitro-owner-browser','1');return;}if(localStorage.getItem('nitro-owner-browser')==='1')return;}catch{}const originalPath=location.pathname+location.search+location.hash;if(window.__nitroTrackedPath===originalPath)return;window.__nitroTrackedPath=originalPath;const p=new URLSearchParams(location.search);let attribution={};try{const queryId=p.get('oid'),queryToken=p.get('ot');if(queryId&&queryToken){attribution={id:queryId,token:queryToken};sessionStorage.setItem('nitro-outreach-attribution',JSON.stringify(attribution));p.delete('oid');p.delete('ot');const cleanQuery=p.toString();history.replaceState(null,'',location.pathname+(cleanQuery?'?'+cleanQuery:'')+location.hash);}else{attribution=outreachAttribution();}}catch{}const path=location.pathname+(p.toString()?'?'+p.toString():'')+location.hash;const priorPath=sessionStorage.getItem('nitro-outreach-first-path');if(attribution.id&&!priorPath)sessionStorage.setItem('nitro-outreach-first-path',path);else if(attribution.id&&priorPath!==path)confirmOutreachVisit('navigation');fetch('/api/track-visit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({visitorId:analyticsId(localStorage,'nitro-visitor-id'),sessionId:analyticsId(sessionStorage,'nitro-visit-session-v2'),path,pageTitle:document.title,referrer:document.referrer,utmSource:p.get('utm_source')||'',utmMedium:p.get('utm_medium')||'',utmCampaign:p.get('utm_campaign')||'',outreachId:attribution.id||'',outreachToken:attribution.token||'',webdriver:navigator.webdriver===true,visibility:document.visibilityState})}).then(()=>bindOutreachEngagement()).catch(()=>{});}
function syncRouteMeta(r){
  const clean=r==='/'?'/':r;
  const indexable=new Set(['/','/start','/pricing','/audit','/privacy','/terms']);
  const descriptions={
    '/':'Build websites, create posts and carousels, schedule Instagram posts, plan ads, and manage outreach from one focused workspace.',
    '/start':'Build a free Nitro workspace for your independent business—no credit card or sales call required.',
    '/pricing':'Compare Nitro Outreach plans for websites, content, social scheduling, advertising, outreach, and analytics.',
    '/audit':'Get a free evidence-based website growth audit covering conversion clarity, trust, SEO foundations, and accessibility.',
    '/privacy':'Read the Nitro Outreach privacy policy.', '/terms':'Read the Nitro Outreach terms of service.'
  };
  const canonical=document.querySelector('link[rel="canonical"]');if(canonical)canonical.href=location.origin+clean;
  let robots=document.querySelector('meta[name="robots"]');if(!robots){robots=document.createElement('meta');robots.name='robots';document.head.appendChild(robots);}robots.content=indexable.has(clean)?'index, follow':'noindex, nofollow';
  const description=document.querySelector('meta[name="description"]');if(description)description.content=descriptions[clean]||'Nitro Outreach customer workspace.';
  document.querySelector('meta[property="og:url"]')?.setAttribute('content',location.origin+clean);
  document.querySelector('meta[property="og:title"]')?.setAttribute('content',document.title);
  document.querySelector('meta[name="twitter:title"]')?.setAttribute('content',document.title);
}
function render(){const r=route(),stackedHome=r==='/',stackedTheme=stackedHome||r==='/pricing';setStackedLandingStyles(stackedTheme);let html;if(stackedHome)html=renderLanding();else if(r==='/start')html=renderStart();else if(r==='/audit')html=renderAudit();else if(r==='/report')html=renderReport();else if(r==='/login')html=renderLogin();else if(r==='/signup')html=renderSignup();else if(r==='/forgot-password')html=renderForgot();else if(r==='/verify-email')html=renderVerify();else if(r==='/reset-password')html=renderReset();else if(r==='/pricing')html=renderPricing();else if(r==='/privacy')html=legalPage('privacy');else if(r==='/terms')html=legalPage('terms');else if(r==='/welcome')html=renderWelcome();else if(r==='/checkout')html=renderCheckout();else if(r==='/checkout/payment')html=renderPayment();else if(r==='/checkout/success')html=renderSuccess();else if(r==='/app'||r.startsWith('/app/'))html=appShell();else html=renderLanding();syncRouteMeta(r);root.innerHTML=html;bindCommon();bindAuth();bindOnboarding();bindCheckout();bindApp();animateUI();trackPageView();if(stackedHome)hydrateStackedLanding();}
function showCheckoutReturnNotice(){
  const params=new URLSearchParams(location.search);
  const upgraded=params.get('upgraded')==='1';
  const credits=params.get('contentCredits')==='success'||params.get('videoCredits')==='success';
  if(!upgraded&&!credits)return;
  toast(upgraded?'Payment complete. Your plan is being activated now.':'Payment complete. Your Content credits are being added now.','success');
  history.replaceState(null,'',location.pathname+location.hash);
  setTimeout(async()=>{await loadSession();render();},1600);
}

const SPA_PATHS=new Set(['/','/start','/audit','/report','/login','/signup','/forgot-password','/verify-email','/reset-password','/pricing','/privacy','/terms','/welcome','/checkout','/checkout/payment','/checkout/success']);
function isSpaPath(pathname){const clean=pathname.replace(/\/+$/,'')||'/';return SPA_PATHS.has(clean)||clean==='/app'||clean.startsWith('/app/');}
function scrollToRouteHash(){if(!location.hash)return;requestAnimationFrame(()=>document.getElementById(decodeURIComponent(location.hash.slice(1)))?.scrollIntoView({behavior:'smooth',block:'start'}));}
function resetWorkspaceRoutePosition(){
  document.querySelector('.desktop-quick-wrap')?.classList.remove('open');
  document.getElementById('desktop-quick-menu')?.setAttribute('aria-expanded','false');
  document.querySelector('.sidebar-primary-nav')?.scrollTo({top:0,behavior:'instant'});
  scrollTo({top:0,left:0,behavior:'instant'});
}
function navigateSpa(url,replace=false){
  const next=url instanceof URL?url:new URL(url,location.href);
  if(next.origin!==location.origin||!isSpaPath(next.pathname))return false;
  const sameDocument=next.pathname===location.pathname&&next.search===location.search;
  if(sameDocument&&next.hash&&route()==='/'){
    if(next.href!==location.href)(replace?history.replaceState(null,'',next):history.pushState(null,'',next));
    scrollToRouteHash();
    return true;
  }
  replace?history.replaceState(null,'',next):history.pushState(null,'',next);
  state.mobileMenu=false;
  render();
  scrollToRouteHash();
  return true;
}
document.addEventListener('click',event=>{
  if(event.defaultPrevented||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;
  const link=event.target.closest('a[href]');
  if(!link||link.target||link.hasAttribute('download'))return;
  const href=link.getAttribute('href');
  if(!href||href.startsWith('mailto:')||href.startsWith('tel:')||href.startsWith('javascript:'))return;
  const next=new URL(href,location.href);
  if(next.origin!==location.origin||!isSpaPath(next.pathname))return;
  event.preventDefault();
  navigateSpa(next);
});
window.addEventListener('popstate',()=>{state.mobileMenu=false;render();scrollToRouteHash();});
window.addEventListener('hashchange',()=>{if(route()==='/'&&location.hash){scrollToRouteHash();return;}state.mobileMenu=false;resetWorkspaceRoutePosition();render();});
const initialRoute=route();
const protectedInitialRoute=['/app','/welcome','/checkout'].some(path=>initialRoute===path||initialRoute.startsWith(path+'/'));
if(protectedInitialRoute){
  syncRouteMeta(initialRoute);
  root.innerHTML='<main class="route-loading-shell" aria-busy="true" aria-live="polite"><div class="route-loading-brand"><span class="brand-mark">N</span><b>Nitro Outreach</b></div><div class="route-loading-card"><i></i><span>Loading your workspace…</span></div></main>';
}else render();
loadSession().then(()=>{render();showCheckoutReturnNotice();scrollToRouteHash();});
